mapper.select:
select m.message_id, m.session_id, m.role, m.parts_json, m.metadata_json, m.create_time
from crm_ai_chat_message m
inner join crm_ai_chat_session s on s.session_id = m.session_id
where m.session_id = #{sessionId}
  and m.tenant_id = #{tenantId}
  and s.user_id = #{userId}
  and s.del_flag = '0'
order by m.create_time asc

select message_id, session_id, tenant_id, role, parts_json, metadata_json, create_time
from crm_ai_chat_message
where message_id = #{messageId}

mapper.insert:
insert into crm_ai_chat_message (
    message_id, session_id, tenant_id, role, parts_json, metadata_json, create_time
) values (
    #{messageId}, #{sessionId}, #{tenantId}, #{role}, #{partsJson}, #{metadataJson}, #{createTime}
)

mapper.update:
update crm_ai_chat_message
set role = #{role},
    parts_json = #{partsJson},
    metadata_json = #{metadataJson}
where message_id = #{messageId}
  and session_id = #{sessionId}
  and tenant_id = #{tenantId}
